ALTER TABLE public.call_sessions ADD COLUMN request_id uuid, ADD COLUMN source text NOT NULL DEFAULT 'staff', ADD COLUMN sync_error text;
CREATE UNIQUE INDEX call_sessions_request_unique ON public.call_sessions(organization_id,request_id);
ALTER TABLE public.call_attempts ADD COLUMN session_id uuid REFERENCES public.call_sessions(id), ADD COLUMN duration_seconds integer NOT NULL DEFAULT 0;
CREATE TABLE public.public_surveys (id text PRIMARY KEY, organization_id uuid NOT NULL REFERENCES public.organizations(id), answers jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.public_surveys TO service_role;
ALTER TABLE public.public_surveys ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.public_ip_windows (ip_hash text PRIMARY KEY, window_start timestamptz NOT NULL DEFAULT now(), requests integer NOT NULL DEFAULT 1);
GRANT ALL ON public.public_ip_windows TO service_role;
ALTER TABLE public.public_ip_windows ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.consume_public_request(p_hash text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN INSERT INTO public.public_ip_windows(ip_hash) VALUES(p_hash) ON CONFLICT(ip_hash) DO UPDATE SET requests=CASE WHEN public_ip_windows.window_start < now()-interval '1 minute' THEN 1 ELSE public_ip_windows.requests+1 END, window_start=CASE WHEN public_ip_windows.window_start < now()-interval '1 minute' THEN now() ELSE public_ip_windows.window_start END RETURNING requests INTO n; RETURN n<=30; END $$;
REVOKE ALL ON FUNCTION public.consume_public_request(text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.consume_public_request(text) TO service_role;
CREATE FUNCTION public.save_call_result(p_request uuid,p_contact text,p_company text,p_company_name text,p_contact_name text,p_phone text,p_result text,p_duration integer,p_notes text,p_callback jsonb DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE oid uuid; sid uuid; cname text; BEGIN oid=public.current_org_id(); IF oid IS NULL OR auth.uid() IS NULL THEN RAISE EXCEPTION 'Login vereist'; END IF; IF p_result NOT IN ('bereikt','geenGehoor','voicemail','terugbellenGepland','afspraak','nietInteressant','nietBellen','enqueteTel','enqueteVerstuurd','anderMoment') OR p_duration<0 OR p_duration>86400 OR length(p_notes)>5000 OR length(p_contact)>100 THEN RAISE EXCEPTION 'Ongeldige uitkomst'; END IF; PERFORM 1 FROM public.organizations WHERE id=oid FOR UPDATE; SELECT id INTO sid FROM public.call_sessions WHERE organization_id=oid AND request_id=p_request; IF sid IS NOT NULL THEN RETURN sid; END IF; SELECT name INTO cname FROM public.profiles WHERE auth_user_id=auth.uid(); INSERT INTO public.call_sessions(organization_id,request_id,contact_id,company_id,company_name,contact_name,phone,caller_id,caller_name,started_at,ended_at,duration_seconds,result,notes) VALUES(oid,p_request,p_contact,p_company,p_company_name,p_contact_name,p_phone,auth.uid(),cname,now()-make_interval(secs=>p_duration),now(),p_duration,p_result,p_notes) RETURNING id INTO sid; INSERT INTO public.call_attempts(organization_id,session_id,contact_id,company_id,result,caller_id,duration_seconds) VALUES(oid,sid,p_contact,p_company,p_result,auth.uid(),p_duration); IF p_result='nietBellen' THEN INSERT INTO public.dnc_list(organization_id,phone,phone_norm,reason,added_by) VALUES(oid,p_phone,p_phone,'Niet bellen',auth.uid()) ON CONFLICT(organization_id,phone_norm) DO NOTHING; END IF; IF p_result='terugbellenGepland' THEN IF p_callback IS NULL THEN RAISE EXCEPTION 'Terugbeldatum ontbreekt'; END IF; INSERT INTO public.callbacks(organization_id,contact_id,contact_name,company_name,scheduled_date,scheduled_time,note,created_by,assigned_to) VALUES(oid,p_contact,p_contact_name,p_company_name,(p_callback->>'date')::date,p_callback->>'time',coalesce(p_callback->>'note',''),public.current_profile_id(),public.current_profile_id()); END IF; RETURN sid; END $$;
REVOKE ALL ON FUNCTION public.save_call_result(uuid,text,text,text,text,text,text,integer,text,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_call_result(uuid,text,text,text,text,text,text,integer,text,jsonb) TO authenticated;